import{_ as e,o as t,c as a,Q as r}from"./chunks/framework.b67c47e6.js";const g=JSON.parse('{"title":"BTL File (Wood Profiles)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/formats/wood_btl/index.md","filePath":"guide/machine_files/formats/wood_btl/index.md","lastUpdated":1790016780000}'),s={name:"guide/machine_files/formats/wood_btl/index.md"},o=r('<h1 id="btl-file-wood-profiles" tabindex="-1">BTL File (Wood Profiles) <a class="header-anchor" href="#btl-file-wood-profiles" aria-label="Permalink to &quot;BTL File (Wood Profiles)&quot;">​</a></h1><p>The BTL format generates cutting instructions for wood profile processing machines. It&#39;s used by Hundegger and H&amp;M Truss Master equipment for cutting studs, beams, and other timber members.</p><nav class="table-of-contents"><ul><li><a href="#output">Output</a></li><li><a href="#parameters">Parameters</a><ul><li><a href="#part-data-fields">Part data fields</a></li><li><a href="#user-attributes">User Attributes</a></li><li><a href="#properties">Properties</a></li></ul></li></ul></nav><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> ZIP containing <code>.btl</code> files</li><li><strong>Target machines:</strong> H&amp;M Truss Master, Hundegger Speed-Cut, Hundegger Turbo-Drive</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><table><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Group parts</strong></td><td>How to organize output files: &#39;By Panel&#39;, &#39;By Batch&#39;, or &#39;By Phase&#39;.</td><td>By Panel</td></tr><tr><td><strong>Split shared references per panel</strong></td><td>Only when grouping By Batch or By Phase. Keeps a reference that appears in several panels as one entry <strong>per panel</strong> — each with its own quantity and its own panel fields — instead of merging them into a single line. Example: <code>P50</code> used 3× in one panel and 2× in another produces two entries (count 3 and count 2).</td><td>Off</td></tr><tr><td><strong>Split by sizes</strong></td><td>Create separate files for each profile size.</td><td>Off</td></tr><tr><td><strong>Create marks</strong></td><td>Add marks/labels on processed parts.</td><td>Off</td></tr><tr><td><strong>Angle decimal places</strong></td><td>Number of decimal places for angle values.</td><td>1</td></tr><tr><td><strong>Filter parts by prefix</strong></td><td>Only include parts whose reference starts with specific prefixes.</td><td>—</td></tr></tbody></table><h3 id="part-data-fields" tabindex="-1">Part data fields <a class="header-anchor" href="#part-data-fields" aria-label="Permalink to &quot;Part data fields&quot;">​</a></h3><p>The standard &quot;Part data&quot; fields that your machine/SCM software reads — <strong>Designation, Assembly number, Group, Package, Material, Timber grade, Quality grade</strong> and <strong>Subgroup / Storey</strong> — can now be filled with whatever you want, per machine. Each field is a small template where you type free text and/or <strong>properties</strong> wrapped in curly braces (see below). This lets you export a whole <strong>batch or phase</strong> in a single file while every part still carries its own panel identity, instead of having to export panel by panel.</p><p>For example, setting <strong>Designation</strong> to <code>{part_pos} ; {assembly_name}</code> produces values like <code>5461 ; HD-529</code>.</p><p>The defaults reproduce the previous behaviour, so nothing changes until you edit a field. These fields apply to the BTL and BTLx files (not to the panel-frame BTL).</p><h3 id="user-attributes" tabindex="-1">User Attributes <a class="header-anchor" href="#user-attributes" aria-label="Permalink to &quot;User Attributes&quot;">​</a></h3><p>You can define up to 5 custom attributes that are embedded in the BTL file. Each has a <strong>name</strong> and <strong>value</strong> field. Use these to pass additional metadata to your machine software.</p><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h3><p>Both the part data fields and the user attribute values accept <strong>properties</strong> in curly braces, replaced per part — <code>{part_pos}</code>, <code>{assembly_name}</code>, <code>{material}</code>, <code>{batch}</code>, your own model properties, and so on. Each field has an <strong>Insert property</strong> button listing everything it accepts.</p><p>The full list, the rules and where else properties work: <strong><a href="/guide/properties/">Properties in texts</a></strong>.</p>',16),i=[o];function n(d,l,p,h,u,c){return t(),a("div",null,i)}const m=e(s,[["render",n]]);export{g as __pageData,m as default};
